head.script:
scwin.onpageload = function() {};
scwin.trigger1_onclick = function(e) {
    count++;
    widgetContainer1.addWidgets({
        id: "widget_" + count,
        title: "위젯" + count,
        src: "widget.xml",
        scope: true,
        x: 0,
        y: 0,
        unitWidth: 1,
        unitHeight: 10,
        minUnitWidth: 10,
        minUnitHeight: 10,
        minimized: false,
        resized: false,
    });
};
scwin.trigger2_onclick = function(e) {
    count1++;
    widgetContainer2.addWidgets({
        id: "widget" + count1,
        title: "위젯" + count1,
        src: "widget.xml",
        scope: true,
        x: 0,
        y: 0,
        unitWidth: 1,
        unitHeight: 10,
        minimized: false,
        resized: false,
    });
};
scwin.trigger3_onclick = function(e) {
    var widgetStr = "";
    widgetStr += "<w2:widgetContainer xmlns:w2='http://www.inswave.com/websquare' id='widgetContainer3' unitHeightPixel='200' mode='switch' widgetMove='true' cols='3' ";
    widgetStr += " style='position: relative ;width:100%;height:100%;border:1px solid black;'>";
    widgetStr += "</w2:widgetContainer>";
    debugger;
    WebSquare.util.dynamicCreate("widgetContainer3", "widgetContainer", widgetStr, group1);
};
scwin.widgetContainer1_onwidgetmove = function(id, newRect, oldRect) {
    var widget = widgetContainer1.getWidgetById(id);
    var widgetInfo = widget.getWidgetInfo();
    console.log("onwidgetmove:", widgetInfo);
};
scwin.widgetContainer1_onwidgetresize = function(id, newRect, oldRect) {
    console.log("onwidgetresize: ", arguments);
    console.log("before: ", widgetContainer1.getWidgetById(id).unitHeight)
    if (newRect.unitHeight <= 2) {
        widgetContainer1.resizeWidget(id, 4, 4, {
            force: true
        });
    }
    console.log("after: ", widgetContainer1.getWidgetById(id).unitHeight)
};
scwin.widgetContainer2_onwidgetresize = function(id, newRect, oldRect) {
    console.log("onwidgetresize2: ", arguments);
    console.log("before2: ", widgetContainer2.getWidgetById(id).unitHeight)
    if (newRect.unitHeight <= 1) {
        widgetContainer2.resizeWidget(id, 3, 2, {
            force: true
        });
    }
    console.log("after2: ", widgetContainer2.getWidgetById(id).unitHeight)
};
scwin.trigger4_onclick = function(e) {
    var x = widgetContainer1.exportWidgets();
    //JSON.stringify(x,null,"\t");
    console.log(JSON.stringify(x, null, "\t"));
    //id가 "1","2" 로 확인됨."widget_1","widget_2" 로 addWidgets 하였으나.
};
scwin.trigger5_onclick = function(e) {
    widgetContainer1.removeWidgetsAll();
};
scwin.trigger6_onclick = function(e) {
    widgetContainer1.enableWidgetResize(scwin.isResizable);
    scwin.isResizable = !scwin.isResizable;
};
scwin.trigger7_onclick = function(e) {
    widgetContainer2.removeWidgetsAll();
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.count = 0;
    window.count1 = 0;
    scwin.isResizable = true;
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
